{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people by placing refreshment sets and entertainment control near seating areas.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_set",
        "entity_kind": "OBJECT",
        "function": "A plate and cup provided to one person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "drinkware"],
        "required_properties": ["holds_food_or_drink"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "switch", "control_panel"],
        "required_properties": ["operates_tv"]
      },
      {
        "id": "seating_spot",
        "entity_kind": "REGION",
        "function": "A chair or seat for a person to occupy.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair", "seat", "sofa"],
        "required_properties": ["supportive_for_sitting"]
      },
      {
        "id": "service_surface",
        "entity_kind": "REGION",
        "function": "A table or surface to hold refreshments and controls.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "bench", "desk"],
        "required_properties": ["flat_surface"]
      },
      {
        "id": "source_surface",
        "entity_kind": "REGION",
        "function": "The surface where items currently reside before moving.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "shelf"],
        "required_properties": ["holds_items"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_proximity",
        "relation": "near",
        "participant_roles": ["refreshment_set", "seating_spot"]
      ,
        "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "accessible_to",
        "participant_roles": ["entertainment_control", "seating_spot"]
      ,
        "required": true
      },
      {
        "id": "items_on_surface",
        "relation": "on",
        "participant_roles": ["refreshment_set", "service_surface"]
      ,
        "required": true
      },
      {
        "id": "control_on_surface",
        "relation": "on",
        "participant_roles": ["entertainment_control", "service_surface"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "move_refreshments",
        "operation": "move",
        "participant_roles": ["refreshment_set", "source_surface", "service_surface"],
        "operation_count": 2
      },
      {
        "id": "move_control",
        "operation": "move",
        "participant_roles": ["entertainment_control", "source_surface", "service_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_set": [
        {
          "label": "Cup and plate on console table",
          "visual_description": "Red cup and white plate visible on the wooden console table in the foreground/right."
        }
      ],
      "entertainment_control": [
        {
          "label": "Remote on console table",
          "visual_description": "Black remote control visible on the wooden console table next to the cups."
        }
      ],
      "seating_spot": [
        {
          "label": "Left armchair",
          "visual_description": "Wooden armchair with black cushion facing the TV."
        },
        {
          "label": "Right armchair",
          "visual_description": "Wooden armchair with black cushion facing the TV."
        }
      ],
      "service_surface": [
        {
          "label": "Coffee table",
          "visual_description": "Low rectangular table with green top between the two chairs."
        },
        {
          "label": "TV Bench",
          "visual_description": "Long wooden bench placed directly beneath the wall-mounted television."
        }
      ],
      "source_surface": [
        {
          "label": "Console table",
          "visual_description": "Wooden table in the foreground/right holding the cups, plates, and remote."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "console_table_storage",
        "label": "Drawers/Shelves under console table",
        "visual_description": "Carved wooden panels under the console table, possibly concealing storage.",
        "reason": "Could contain additional refreshment items or controls if needed."
      },
      {
        "id": "coffee_table_storage",
        "label": "Drawers/Shelves under coffee table",
        "visual_description": "Carved wooden panels under the coffee table.",
        "reason": "Could provide a surface or storage for items."
      },
      {
        "id": "tv_bench_storage",
        "label": "Storage under TV bench",
        "visual_description": "Wooden slats under the bench beneath the TV.",
        "reason": "Could be used as a service surface."
      }
    ],
    "inspection_order": [
      "console_table_storage",
      "coffee_table_storage",
      "tv_bench_storage"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
